func (_c *AdBoostCreateBulk) OnConflictColumns(columns ...string) *AdBoostUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &AdBoostUpsertBulk{
		create: _c,
	}
}

// AdBoostUpsertBulk is the builder for "upsert"-ing
// a bulk of AdBoost nodes.
type AdBoostUpsertBulk struct {
	create *AdBoostCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.AdBoost.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(adboost.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *AdBoostUpsertBulk) UpdateNewValues() *AdBoostUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(adboost.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(adboost.FieldCreatedAt)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(adboost.FieldUserID)
			}
			if _, exists := b.mutation.PostID(); exists {
				s.SetIgnore(adboost.FieldPostID)
			}
			if _, exists := b.mutation.DestinationType(); exists {
				s.SetIgnore(adboost.FieldDestinationType)
			}
			if _, exists := b.mutation.Goal(); exists {
				s.SetIgnore(adboost.FieldGoal)
			}
			if _, exists := b.mutation.Audience(); exists {
				s.SetIgnore(adboost.FieldAudience)
			}
			if _, exists := b.mutation.Currency(); exists {
				s.SetIgnore(adboost.FieldCurrency)
			}
			if _, exists := b.mutation.BudgetType(); exists {
				s.SetIgnore(adboost.FieldBudgetType)
			}
			if _, exists := b.mutation.PaymentMethod(); exists {
				s.SetIgnore(adboost.FieldPaymentMethod)
			}
			if _, exists := b.mutation.IdempotencyKey(); exists {
				s.SetIgnore(adboost.FieldIdempotencyKey)
			}
			if _, exists := b.mutation.RequestHash(); exists {
				s.SetIgnore(adboost.FieldRequestHash)
			}
			if _, exists := b.mutation.AccountID(); exists {
				s.SetIgnore(adboost.FieldAccountID)
			}
			if _, exists := b.mutation.CampaignID(); exists {
				s.SetIgnore(adboost.FieldCampaignID)
			}
			if _, exists := b.mutation.AdGroupID(); exists {
				s.SetIgnore(adboost.FieldAdGroupID)
			}
			if _, exists := b.mutation.AdID(); exists {
				s.SetIgnore(adboost.FieldAdID)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.AdBoost.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *AdBoostUpsertBulk) Ignore() *AdBoostUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *AdBoostUpsertBulk) DoNothing() *AdBoostUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the AdBoostCreateBulk.OnConflict
// documentation for more info.
func (u *AdBoostUpsertBulk) Update(set func(*AdBoostUpsert)) *AdBoostUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&AdBoostUpsert{UpdateSet: update})
	}))
	return u
}

